function [v, mode, idx] = kpi_mode_fraction(mode, idx, ni, m)
%KPI_MODE_FRACTION  The share [%] of the window's samples idx[0..ni] in the mode m.
%   length: 64
%   mode: inout int[*] (passed a whole number)
%   idx: inout int[*] (passed a whole number)
%   ni: int (passed a whole number)
%   m: int (passed a whole number)
%   returns v: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    v = 0;
    k = 0;
    for i = (0):((ni) - 1)
        if (mode((idx((i) + 1)) + 1) == m)
            k = (k + 1);
        end
    end
    d = ni;
    if (d < 1)
        d = 1;
    end
    v = ((100 * k) / d);
end
